function standInStations(c: number, connections: number[][], queries: number[][]): number[] {
  const adj: number[][] = Array.from({ length: c + 1 }, () => []);
  for (const [a, b] of connections) { adj[a].push(b); adj[b].push(a); }
  const off = new Array(c + 1).fill(false);
  const out: number[] = [];
  for (const [t, x] of queries) {
    if (t === 2) { off[x] = true; continue; }
    if (!off[x]) { out.push(x); continue; }
    const seen = new Array(c + 1).fill(false);
    const stack = [x];
    seen[x] = true;
    let best = -1;
    while (stack.length) {
      const u = stack.pop()!;
      if (!off[u] && (best === -1 || u < best)) best = u;
      for (const v of adj[u]) if (!seen[v]) { seen[v] = true; stack.push(v); }
    }
    out.push(best);
  }
  return out;
}

