function standInStations(c: number, connections: number[][], queries: number[][]): number[] {
  const parent = new Int32Array(c + 1);
  for (let i = 0; i <= c; i++) parent[i] = i;
  const find = (x: number): number => {
    let root = x;
    while (parent[root] !== root) root = parent[root];
    while (parent[x] !== root) { const nx = parent[x]; parent[x] = root; x = nx; }
    return root;
  };
  for (const [a, b] of connections) {
    const ra = find(a), rb = find(b);
    if (ra !== rb) parent[ra] = rb;
  }
  const members = new Map<number, number[]>();
  for (let id = 1; id <= c; id++) {
    const r = find(id);
    if (!members.has(r)) members.set(r, []);
    members.get(r)!.push(id); // ids arrive in increasing order
  }
  const ptr = new Int32Array(c + 1);
  const off = new Uint8Array(c + 1);
  const out: number[] = [];
  for (const [t, x] of queries) {
    if (t === 2) { off[x] = 1; continue; }
    if (!off[x]) { out.push(x); continue; }
    const r = find(x), list = members.get(r)!;
    while (ptr[r] < list.length && off[list[ptr[r]]]) ptr[r]++;
    out.push(ptr[r] < list.length ? list[ptr[r]] : -1);
  }
  return out;
}

