    def standInStations(self, c: int, connections: List[List[int]], queries: List[List[int]]) -> List[int]:
        parent = list(range(c + 1))

        def find(x: int) -> int:
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        for a, b in connections:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
        members = defaultdict(list)
        for i in range(1, c + 1):
            members[find(i)].append(i)  # ids arrive in increasing order
        ptr = [0] * (c + 1)
        off = [False] * (c + 1)
        out = []
        for t, x in queries:
            if t == 2:
                off[x] = True
            elif not off[x]:
                out.append(x)
            else:
                r = find(x)
                lst = members[r]
                p = ptr[r]
                while p < len(lst) and off[lst[p]]:
                    p += 1
                ptr[r] = p
                out.append(lst[p] if p < len(lst) else -1)
        return out

